OPENROUTER_MODEL = "google/gemini-3.8-flash"  # any OpenRouter model slug

SCRAPING_LOOKBACK_DAYS = 5

companies = {
    "mbank": ("109", "MBK.WA", "mBank SA świadczy usługi bankowe dla klientów korporacyjnych, instytucjonalnych i detalicznych na terenie Polski. Prowadzi działalność w zakresie obsługi klientów korporacyjnych, instytucjonalnych i detalicznych (w tym private banking) na terenie całego kraju oraz działalność handlową i inwestycyjną, a także maklerską. Bank oferuje usługi dla osób prawnych i fizycznych, krajowych i zagranicznych, zarówno w złotych jak i w walutach obcych. W ramach bankowości detalicznej mBanku działają oddziały zagraniczne w Czechach i na Słowacji. Bank może otwierać i posiadać rachunki w bankach polskich i zagranicznych oraz ma prawo posiadania wartości dewizowych i dokonywania obrotu nimi. mBank oferuje szeroki zakres produktów i usług, w tym rachunki bieżące i oszczędnościowe, produkty kredytowe, depozytowe, karty płatnicze, produkty inwestycyjne i ubezpieczeniowe."),
    "budimex": ("112", "BDX.WA", "Budimex SA jest jedną z największych firm budowlanych w Polsce. Działa jako generalny wykonawca w sektorach infrastruktury drogowej, kolejowej, lotniskowej oraz budownictwa kubaturowego, energetycznego, przemysłowego i ekologicznego. Grupa rozszerza działalność w obszarze facility management (obsługa nieruchomości i obiektów infrastruktury) oraz gospodarki odpadami. Realizuje projekty w Polsce oraz na rynkach zagranicznych, w tym na Słowacji, w Czechach i na Łotwie. Inwestorem strategicznym Budimeksu jest hiszpańska firma Ferrovial."),
    "erste": ("117", "EBP.WA", "Erste Bank oferuje nowoczesne rozwiązania finansowe dla osób indywidualnych, mikro, małych i średnich przedsiębiorstw oraz polskich i międzynarodowych korporacji. Posiada jedną z największych sieci oddziałów i placówek partnerskich, jak również świadczy usługi poprzez elektroniczne kanały dostępu, w tym bankowość mobilną. Jest jednym z liderów rynku w zakresie wykorzystania nowoczesnych technologii w usługach bankowych. Spółki z Grupy oferują m.in. fundusze inwestycyjne, usługi maklerskie, ubezpieczenia, leasing oraz faktoring."),
    "modivo": ("456", "MDV.WA", "Spółka działa w segmencie obuwia i odzieży na 20 rynkach europejskich, łącząc sprzedaż stacjonarną (ponad 1300 sklepów) z e-commerce. W skład grupy wchodzą marki i formaty: CCC, HalfPrice, eobuwie, MODIVO, worldbox i Boardriders. Sprzedaż wspiera program lojalnościowy MODIVOclub, obejmujący wszystkie szyldy grupy."),
    "kety": ("274", "KTY.WA", "Kęty (Grupa Kęty) — Grupa prowadzi działalność w trzech segmentach operacyjnych. Segment Wyrobów Wyciskanych obejmuje produkcję i sprzedaż profili oraz komponentów aluminiowych. Segment Systemów Aluminiowych dostarcza systemy aluminiowe dla budownictwa i świadczy usługi budowlano-montażowe. Segment Opakowań Giętkich wytwarza opakowania giętkie i folie polipropylenowe BOPP. Spółka oferuje produkty i usługi w ponad 50 krajach. Grupa Kapitałowa składa się z 24 spółek, w tym 15 zagranicznych. Główne rynki zbytu to branże: budowlana, motoryzacyjna, spożywcza i farmaceutyczna."),
    "kghm": ("350", "KGH.WA", "KGHM Polska Miedź S.A. jest wiodącym producentem miedzi i srebra na świecie. Spółka eksploatuje złoża miedzi w Polsce oraz posiada projekty wydobywcze w Ameryce Północnej i Południowej. KGHM utrzymał pierwszą pozycję w zestawieniu 'największych kopalń srebra na świecie' oraz drugie miejsce wśród 'największych producentów srebra'. Spółka kontynuuje Program Udostępniania Złoża, realizując 11,7 km wyrobisk górniczych. KGHM rozwija również projekty w zakresie odnawialnych źródeł energii, w tym farmy fotowoltaiczne. Grupa wdraża inicjatywy automatyzacji i cyfryzacji w procesach produkcyjnych, dążąc do zwiększenia efektywności operacyjnej."),
    "lpp": ("380", "LPP.WA", "LPP — Grupa zajmuje się projektowaniem, produkcją i dystrybucją odzieży poprzez sieć sprzedaży obejmującą 39 krajów na 3 kontynentach. Posiada 5 rozpoznawalnych marek: Sinsay, Reserved, Cropp, House i Mohito, każda skierowana do innej grupy docelowej. Sprzedaż odbywa się w sklepach stacjonarnych i internetowych w modelu omnichannel. Sieć sprzedaży stacjonarnej liczy 2382 sklepy o łącznej powierzchni 2081 tys. mkw. w 28 krajach. Online grupa jest obecna na 34 rynkach. Koncepcje kolekcji powstają w Polsce, a produkcja zlecana jest głównie firmom z Azji."),
    "cdprojekt": ("476", "CDR.WA", "CD Projekt — Grupa i jej spółka dominująca prowadzą działalność w globalnej branży elektronicznej rozrywki. Grupa koncentruje się na produkcji i wydawaniu gier wideo oraz zarządzaniu posiadanymi markami, m.in. poprzez tworzenie i licencjonowanie produktów towarzyszących. Flagowymi tytułami studia CD Projekt Red są Cyberpunk 2077, w tym dodatek Widmo wolności w klimacie szpiegowskiego thrillera, oraz seria gier o Wiedźminie, w tym Wiedźmin 3: Dziki Gon i dodatki Serca z kamienia oraz Krew i wino."),
    "pekao": ("76", "PEO.WA", "Bank Pekao SA jest uniwersalnym bankiem komercyjnym, drugim co do wielkości w Polsce. Oferuje szeroki zakres usług bankowych dla klientów indywidualnych i instytucjonalnych, głównie na rynku polskim. Grupa Kapitałowa Banku Pekao SA obejmuje instytucje finansowe działające w obszarach bankowości, zarządzania aktywami, usług maklerskich, leasingu i faktoringu. Bank posiada rozbudowaną sieć oddziałów i bankomatów na terenie całego kraju oraz nowoczesne kanały bankowości elektronicznej i mobilnej. Koncentruje się na rozwoju bankowości cyfrowej, upraszczaniu procesów i podnoszeniu jakości obsługi klientów. Oferuje produkty oszczędnościowe, kredytowe, inwestycyjne i ubezpieczeniowe. Jest ważnym partnerem dla przedsiębiorstw i samorządów w finansowaniu rozwoju i inwestycji."),
    "pknorlen": ("511", "PKN.WA", "Grupa ORLEN jest największym w Polsce koncernem multienergetycznym. Główne obszary działalności obejmują przerób ropy naftowej oraz produkcję paliw, wyrobów petrochemicznych i chemicznych. Grupa zajmuje się również wytwarzaniem, dystrybucją i obrotem energią elektryczną i cieplną, w tym z odnawialnych źródeł. ORLEN prowadzi także poszukiwania, rozpoznawanie i wydobycie węglowodorów. Ponadto działalność Grupy obejmuje poszukiwanie i wydobycie gazu ziemnego, import gazu ziemnego, a także magazynowanie, sprzedaż i dystrybucję paliw gazowych i płynnych. Grupa ORLEN oferuje szeroki asortyment produktów, w tym benzyny, olej napędowy, paliwo lotnicze, olej opałowy, tworzywa sztuczne, nawozy i inne produkty petrochemiczne. Prowadzi również sprzedaż detaliczną na stacjach paliw. Działalność Grupy obejmuje także usługi transportowe, remontowe, laboratoryjne i ochrony."),
    "pkobp": ("512", "PKO.WA", "Grupa Kapitałowa PKO Banku Polskiego S.A. należy do największych grup finansowych w Polsce oraz w Europie Środkowo-Wschodniej. PKO Bank Polski S.A. jest największym bankiem komercyjnym w Polsce i liderem krajowego rynku pod względem skali działania, kapitałów własnych, kredytów, oszczędności, liczby klientów oraz wielkości sieci dystrybucji. Bank jest uniwersalnym bankiem depozytowo-kredytowym, obsługującym osoby fizyczne, prawne oraz inne podmioty krajowe i zagraniczne. Grupa oferuje szeroki zakres usług finansowych, w tym kredyty hipoteczne, usługi leasingowe, faktoringowe, zarządzanie funduszami inwestycyjnymi i emerytalnymi oraz ubezpieczenia. Poprzez spółki zależne Grupa świadczy specjalistyczne usługi finansowe w zakresie zarządzania flotą pojazdów, agenta transferowego i dostarczania rozwiązań technologicznych."),
    "orangepl": ("636", "OPL.WA", "Grupa Orange Polska jest wiodącym dostawcą usług telekomunikacyjnych w Polsce. Dostarcza komórkowe i stacjonarne usługi telekomunikacyjne, w tym połączenia głosowe, usługi przesyłu wiadomości i treści, dostęp do Internetu oraz telewizję. Oferta obejmuje również usługi konwergentne łączące mobilny i stacjonarny dostęp do Internetu. Grupa świadczy usługi IT i integracyjne oraz usługi Internetu Rzeczy dla klientów biznesowych. Ponadto oferuje usługi hurtowe innym operatorom, w tym dostęp do infrastruktury sieciowej. Orange Polska prowadzi sprzedaż sprzętu telekomunikacyjnego oraz świadczy usługi w zakresie dzierżawy łączy i transmisji danych. Firma angażuje się w budowę infrastruktury światłowodowej w ramach projektów współfinansowanych ze środków unijnych. Grupa prowadzi również działalność w obszarze obrotu energią elektryczną oraz oferuje wybrane usługi finansowe."),
    "pge": ("503", "PGE.WA", "Grupa PGE jest zintegrowanym pionowo podmiotem energetycznym, działającym w całym łańcuchu wartości energii elektrycznej. To jeden z największych graczy sektora elektroenergetycznego w Polsce. Główne obszary działalności Grupy obejmują wydobycie węgla brunatnego, wytwarzanie energii elektrycznej z paliw kopalnych (węgiel brunatny, węgiel kamienny, gaz ziemny) oraz z odnawialnych źródeł (elektrownie wodne, farmy wiatrowe, biomasa), dystrybucję i sprzedaż energii elektrycznej odbiorcom końcowym. Grupa prowadzi również obrót hurtowy energią elektryczną, gazem, uprawnieniami do emisji CO2 i świadectwami pochodzenia, świadczy usługi systemowe dla bezpieczeństwa dostaw energii oraz prowadzi działalność ciepłowniczą i w obszarze gospodarki obiegu zamkniętego. Grupa posiada zdywersyfikowany miks wytwórczy oparty zarówno na paliwach konwencjonalnych, jak i odnawialnych źródłach energii."),
    "pzu": ("558", "PZU.WA", "Grupa PZU jest jedną z największych instytucji finansowych w Polsce i Europie Środkowo-Wschodniej, oferującą kompleksową ochronę ubezpieczeniową w życiu prywatnym, publicznym i gospodarczym. Oferta obejmuje szeroką gamę produktów, takich jak ubezpieczenia majątkowe, na życie i osobowe. Grupa PZU zarządza także otwartym funduszem emerytalnym, funduszami inwestycyjnymi i programami oszczędnościowymi. W skład Grupy PZU wchodzą PZU SA, PZU Życie SA, Link4 TU SA, TUW PZUW, Alior Bank SA, Bank Pekao SA oraz inne spółki finansowe. Działa głównie w Polsce, ale także w krajach bałtyckich i na Ukrainie. Klientami Grupy są zarówno osoby indywidualne, jak i firmy różnych wielkości. W ubezpieczeniach korporacyjnych Grupa dostosowuje produkty do potrzeb klientów, a w ubezpieczeniach masowych oferuje standardowe produkty. PZU świadczy również usługi bankowe i zarządza aktywami klientów poprzez towarzystwa funduszy inwestycyjnych."),
    "kruk": ("367", "KRU.WA", "Kruk — Grupa jest jednym z liderów na rynku zarządzania wierzytelnościami. Spółka zarządza wierzytelnościami nabytymi na własny rachunek oraz na zlecenie podmiotów zewnętrznych. Główną grupę klientów stanowią banki, a także pośrednicy kredytowi, firmy ubezpieczeniowe, leasingowe, telekomunikacyjne, telewizje kablowe, platformy cyfrowe oraz firmy z sektora dóbr szybko zbywalnych. Poza Polską, grupa prowadzi działalność w Rumunii, Czechach, Słowacji, Niemczech, Hiszpanii i we Włoszech."),
    "alior": ("1180", "ALR.WA", "Alior Bank SA jest uniwersalnym bankiem depozytowo-kredytowym, obsługującym osoby fizyczne, prawne i inne podmioty krajowe i zagraniczne. Podstawowa działalność Banku obejmuje prowadzenie rachunków bankowych, udzielanie kredytów i pożyczek, emitowanie bankowych papierów wartościowych oraz prowadzenie skupu i sprzedaży wartości dewizowych. Bank prowadzi także działalność maklerską, doradztwo i pośrednictwo finansowe oraz świadczy inne usługi finansowe. Grupa oferuje produkty kredytowe, takie jak pożyczki gotówkowe, karty kredytowe, kredyty hipoteczne i ratalne, a także produkty depozytowe, w tym rachunki oszczędnościowo-rozliczeniowe, lokaty terminowe i konta oszczędnościowe. Dodatkowo świadczy usługi transakcyjne, produkty bancassurance oraz oferuje transakcje wymiany walut. Dla klientów biznesowych Bank zapewnia kredyty, produkty depozytowe, rachunki bieżące, usługi transakcyjne, produkty skarbowe, faktoring i leasing."),
    "dinopl": ("1431", "DNP.WA", "Grupa jest jedną z największych w Polsce sieci średniej wielkości supermarketów spożywczych, zlokalizowanych głównie w mniejszych miejscowościach, małych i średnich miastach oraz na peryferiach dużych miast. Na koniec marca 2024 r. sieć liczyła 2 438 sklepów o łącznej powierzchni sali sprzedaży 960 857 mkw. Każdy sklep oferuje około 5 tys. produktów, w tym artykuły świeże i stoisko mięsne z obsługą. Spółka jest właścicielem większości nieruchomości, na których znajdują się sklepy. Sieć zaopatrywana jest przez dziewięć centrów dystrybucyjnych. Model biznesowy obejmuje scentralizowane zarządzanie, sieć logistyczną oraz zarządzaną flotę transportową."),
    "pepco": ("1593", "PCO.WA", "Pepco — Grupa prowadzi europejską sieć dyskontowych sklepów wielobranżowych działających głównie pod marką Pepco. Oferta obejmuje odzież dla dzieci i dorosłych, artykuły wyposażenia domu, zabawki, artykuły sezonowe oraz wybrane produkty codziennego użytku. Sklepy grupy działają w krajach Europy Środkowo-Wschodniej, Południowej i Zachodniej."),
    "zabka": ("1737", "ZAB.WA", "Żabka — Grupa prowadzi sieć sklepów convenience, obejmującą placówki stacjonarne i autonomiczne. Sklepy oferują produkty spożywcze, w tym dania gotowe, kawę, przekąski i kanapki oraz usługi dodatkowe takie jak odbiór paczek, gry losowe i płatności rachunków. Działalność uzupełniają usługi cyfrowe: aplikacja mobilna, catering dietetyczny (Maczfit), platforma do zamawiania diet pudełkowych (Dietly) oraz dostawy zakupów online (delio, Jush!). Infrastrukturę logistyczną w Polsce stanowi osiem centrów dystrybucyjnych i 19 obiektów cross-dock. W Rumunii grupa działa poprzez sieć dystrybucyjną DRIM."),
    "allegro": ("1559", "ALE.WA", "Allegro — Grupa prowadzi platformę handlu internetowego Allegro, działającą w Polsce pod adresem Allegro.pl oraz w Czechach, na Słowacji i na Węgrzech. Platforma łączy sprzedawców zewnętrznych z kupującymi, a grupa prowadzi na niej także własną sprzedaż detaliczną. Uzupełnieniem oferty są usługi dla sprzedawców i kupujących, w tym logistyka i obsługa zamówień w ramach Allegro Fulfillment, sieć automatów paczkowych Allegro One Box, program lojalnościowy Allegro Smart!, płatności odroczone Allegro Pay oraz usługi reklamowe. Do grupy należą również porównywarka cen Ceneo.pl oraz serwis sprzedaży biletów na wydarzenia eBilet. Spółka dominująca z siedzibą w Luksemburgu pełni funkcję holdingu."),
}
